// n8n Code node: "Validate payload"
// The parse-csv Lambda POSTs {batch_id, row_count}. Reject anything that is not a UUID so a
// malformed or hostile request can never reach the SQL stages. (Webhook v2 nests the JSON
// under `body`.)
const raw = $input.first().json;
const b = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const id = String(b.batch_id || '').trim().toLowerCase();
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(id)) {
  throw new Error(`invalid batch_id in webhook payload: ${JSON.stringify(b.batch_id)}`);
}
return [{ json: { batch_id: id, row_count: Number(b.row_count) || 0, received_at: new Date().toISOString() } }];

// n8n Code node: "Stage 0: reconcile lenders"  (mode: Run Once for All Items)
//
// Input : fresh loan_products rows (one item each).
// Output: ONE item per lender. The same lender shows up on several sites with different
//         (sometimes conflicting) thresholds; matching a user against both would list the
//         lender twice in an email, and the strict/lenient disagreement has no right answer.
//         We keep the single most authoritative record and record what was dropped.
//
// Authority order (which record supplies the ELIGIBILITY RULES): the lender's own site > the
// record that states more criteria > aggregator rank (Paisabazaar before BankBazaar) > lower rate.
// The RATE is different: sites disagree (Axis 9.99% vs 8.75%), and a customer cares about the best
// published rate, so effective_rate is the LOWEST rate any source advertises for the lender.
// It is shown as "From X%" because advertised rates are starting rates.

const OFFICIAL = new Set(['bajajfinserv']);
const SOURCE_RANK = { bajajfinserv: 0, paisabazaar: 1, bankbazaar: 2 };
const STOP = new Set(['personal', 'loan', 'bank', 'of', 'india', 'finance', 'finserv', 'first',
                      'mahindra', 'capital', 'ltd', 'limited', 'and']);

// "HDFC Bank Personal Loan" / "HDFC Personal Loan" -> "hdfc"; "Bank of India" -> "bank of india"
function lenderKey(name) {
  const norm = name.toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
  const core = norm.split(' ').filter((t) => !STOP.has(t));
  return core.length ? core.join(' ') : norm.replace(/\s*personal loan$/, '');
}

function completeness(p) {
  let n = 0;
  for (const k of ['min_income', 'min_credit_score', 'min_age', 'max_age']) if (p[k] !== null && p[k] !== undefined) n++;
  return n + (Array.isArray(p.eligibility_rules) ? p.eligibility_rules.length * 0.1 : 0);
}

function better(a, b) {
  const oa = OFFICIAL.has(a.source_site), ob = OFFICIAL.has(b.source_site);
  if (oa !== ob) return oa;
  const ca = completeness(a), cb = completeness(b);
  if (ca !== cb) return ca > cb;
  const ra = SOURCE_RANK[a.source_site] ?? 9, rb = SOURCE_RANK[b.source_site] ?? 9;
  if (ra !== rb) return ra < rb;
  return Number(a.interest_rate) <= Number(b.interest_rate);
}

const groups = new Map();
for (const { json: p } of $input.all()) {
  const key = lenderKey(p.product_name);
  if (!groups.has(key)) groups.set(key, []);
  groups.get(key).push(p);
}

const out = [];
for (const [key, rows] of groups) {
  let best = rows[0];
  for (const r of rows.slice(1)) if (better(r, best)) best = r;
  const rates = rows.map((r) => Number(r.interest_rate)).filter((n) => Number.isFinite(n) && n > 0);
  out.push({
    json: {
      ...best,
      effective_rate: rates.length ? Math.min(...rates) : null,
      rates_seen: rows.map((r) => ({ source_site: r.source_site, interest_rate: r.interest_rate })),
      lender_key: key,
      reconciled_from: rows.map((r) => `${r.source_site}#${r.product_id}`),
      products_in_group: rows.length,
    },
  });
}
console.log(`reconciled ${$input.all().length} products into ${out.length} lenders`);
return out.sort((a, b) => a.json.lender_key.localeCompare(b.json.lender_key));

// n8n Code node: "Collect canonical product ids"  (runs once)
// Folds the reconciled lenders into the single item the SQL stages need.
const lenders = $input.all().map((i) => i.json);
return [{
  json: {
    batch_id: $('Validate payload').first().json.batch_id,
    product_ids: lenders.map((l) => l.product_id),
    // product_id -> lowest published rate across sources (what ranking and emails use)
    product_rates: Object.fromEntries(lenders.map((l) => [l.product_id, l.effective_rate])),
    products_fresh: $('Load fresh products').all().length,
    products_canonical: lenders.length,
    merged_groups: lenders.filter((l) => l.products_in_group > 1).length,
  },
}];

// n8n Code node: "Funnel report"  (runs once, after Stage 3)
// Gathers how many user-product pairs survived each stage. This is the evidence for the
// optimisation: naive pairs vs pairs actually kept. No LLM runs in this workflow.
const first = (n) => $(n).first().json;
const num = (v) => Number(v) || 0;

const collect = first('Collect canonical product ids');
const s1 = first('Stage 1: SQL envelope pre-filter');
const s3 = first('Stage 3: rank and keep top lenders');

const users = num(s1.users_in_batch);
const stats = {
  users_in_batch: users,
  products_fresh: collect.products_fresh,
  products_after_reconcile: collect.products_canonical,
  lenders_merged_groups: collect.merged_groups,
  pairs_naive: users * collect.products_fresh,
  pairs_after_reconcile: users * collect.products_canonical,
  pairs_after_stage1_envelope: num(s1.stage1_pairs),
  pairs_after_stage2_exact_rules: num(s3.stage2_pairs),
  users_with_a_qualifying_lender: num(s3.users_with_a_match),
  top_n_per_user: 5,
  matches_written: num(s3.matches_written),
  matches_flagged_score: num(s3.matches_flagged_score),
  users_matched: num(s3.users_matched),
  llm_calls_in_this_workflow: 0,
  finished_at: new Date().toISOString(),
};
return [{ json: { batch_id: collect.batch_id, stats, stats_json: JSON.stringify(stats) } }];

// n8n Code node: "Prepare review request"
// After matching: ask Workflow R for notes on the lenders this batch's users actually matched.
return [{ json: { scope: 'used', batch_id: $('Validate payload').first().json.batch_id } }];

// n8n Code node: "Prepare hand-off"
// Tells Workflow C which batch just finished, so it emails only that batch's pending matches.
return [{ json: { batch_id: $('Validate payload').first().json.batch_id } }];
